begin;
select * from no_plan();
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000081'), ('00000000-0000-4000-8000-000000000082');
select ok(not has_table_privilege('anon', 'public.subscriptions', p), 'anon cannot ' || p) from unnest(array['SELECT','INSERT','UPDATE','DELETE']) p;
select ok(not has_table_privilege('authenticated', 'public.subscriptions', p), 'authenticated cannot ' || p) from unnest(array['INSERT','UPDATE','DELETE']) p;
select ok(not has_function_privilege(r, f, 'EXECUTE'), r || ' cannot call ' || f)
from unnest(array['anon','authenticated']) r cross join unnest(array['public.get_subscription(uuid)','public.activate_mock_subscription(uuid)','public.cancel_mock_subscription(uuid)']) f;
select is(public.subscription_next_month('2026-01-31 10:00+08'), '2026-02-28 10:00+08'::timestamptz, 'month-end clamped');
select is(public.subscription_next_month('2028-01-31 10:00+08'), '2028-02-29 10:00+08'::timestamptz, 'leap month clamped');
select is(public.subscription_next_month('2026-12-31 10:00+08'), '2027-01-31 10:00+08'::timestamptz, 'year rollover');
set local role service_role;
select is((select status from public.activate_mock_subscription('00000000-0000-4000-8000-000000000081')), 'active', 'service role activates');
select is((select count(*)::int from public.activate_mock_subscription('00000000-0000-4000-8000-000000000081')), 1, 'retry returns one row');
select is((select cancel_at_period_end from public.cancel_mock_subscription('00000000-0000-4000-8000-000000000081')), true, 'cancel preserves access');
select is((select cancel_at_period_end from public.activate_mock_subscription('00000000-0000-4000-8000-000000000081')), true, 'activation retry never undoes cancellation');
select is((select status from public.cancel_mock_subscription('00000000-0000-4000-8000-000000000081')), 'active', 'cancel retry keeps paid status');
reset role;
select is((select current_period_end from public.subscriptions where user_id = '00000000-0000-4000-8000-000000000081'), public.subscription_next_month((select current_period_start from public.subscriptions where user_id = '00000000-0000-4000-8000-000000000081')), 'cancellation does not shorten or extend period');
select throws_ok($$update public.subscriptions set current_period_end = null where user_id = '00000000-0000-4000-8000-000000000081'$$, '23514', null, 'paid subscription requires an end date');
update public.subscriptions set current_period_start = now() - interval '2 months', current_period_end = now() - interval '1 month' where user_id = '00000000-0000-4000-8000-000000000081';
set local role service_role;
select is((select cancel_at_period_end from public.activate_mock_subscription('00000000-0000-4000-8000-000000000081')), false, 'expired mock can start a new uncanceled period');
select ok((select current_period_end > now() from public.get_subscription('00000000-0000-4000-8000-000000000081')), 'reactivation grants a future period');
reset role;
insert into public.subscriptions(user_id,provider,status) values ('00000000-0000-4000-8000-000000000082','ecpay','pending');
select throws_ok($$select public.cancel_mock_subscription('00000000-0000-4000-8000-000000000082')$$, 'P0002', 'Provider integration unavailable', 'provider cancellation cannot pretend success');
select throws_ok($$select public.activate_mock_subscription('00000000-0000-4000-8000-000000000082')$$, 'P0002', 'Provider integration unavailable', 'mock cannot overwrite provider record');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000081',true);
set local role authenticated;
select is((select count(*)::int from public.subscriptions),1,'RLS reads only own row');
select throws_ok($$update public.subscriptions set status = 'active'$$, '42501', 'permission denied for table subscriptions', 'client cannot grant access');
select is((select count(*)::int from public.subscriptions where user_id = '00000000-0000-4000-8000-000000000082'),0,'RLS cannot read another subscription');
select throws_ok($$delete from public.subscriptions$$, '42501', 'permission denied for table subscriptions', 'client cannot delete subscriptions');
select throws_ok($$insert into public.subscriptions(user_id,provider,status) values ('00000000-0000-4000-8000-000000000081','mock','pending')$$, '42501', 'permission denied for table subscriptions', 'client cannot create subscriptions');
reset role;
select * from finish();
rollback;
